-- COMM-09. All user/staff writes are authenticated, narrowly scoped RPCs.
begin;
alter table public.community_reports drop constraint community_reports_reason_check;
alter table public.community_reports add constraint community_reports_reason_check check(reason in ('harassment','offensive_content','impersonation','spam','unsafe_or_sexual_content','other'));
alter table public.community_reports drop constraint community_reports_notes_check;
alter table public.community_reports add constraint community_reports_notes_check check(notes is null or char_length(notes)<=1000);
alter table public.community_reports add column priority text not null default 'normal' check(priority in ('normal','urgent'));
alter table public.community_reports add column assigned_to text;
alter table public.community_reports add column decision text check(decision in ('warn','remove','suspend','ban','dismiss'));
alter table public.community_reports add column decision_reason text check(char_length(decision_reason)<=500);
alter table public.community_reports add column staff_notes text check(char_length(staff_notes)<=1000);
alter table public.community_reports add column action_taken_at timestamptz;
alter table public.community_reports add column suspension_expires_at timestamptz;
alter table public.community_reports add column subject_user_id uuid references auth.users(id) on delete set null;
alter table public.community_reports add column evidence_snapshot jsonb not null default '{}';
create index idx_community_reports_subject on public.community_reports(subject_user_id);
create table public.community_moderation_staff(user_id uuid primary key references auth.users(id) on delete cascade, active boolean not null default false);
create table public.community_report_usage(user_id uuid not null references auth.users(id) on delete cascade,report_date date not null,report_count integer not null check(report_count between 0 and 10),primary key(user_id,report_date));
create table public.community_report_receipts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,target_type text not null check(target_type in ('profile','activity')),target_id text not null,subject_user_id uuid references auth.users(id) on delete set null,evidence_snapshot jsonb not null,created_at timestamptz not null default now(),expires_at timestamptz not null default now()+interval '30 days');
create index idx_community_receipt_user on public.community_report_receipts(user_id,target_type,target_id,expires_at);
create table public.community_moderation_actions(id uuid primary key default gen_random_uuid(),report_id uuid references public.community_reports(id) on delete set null,target_type text not null,target_id text not null,action text not null check(action in ('warn','remove','suspend','ban','dismiss','reverse','inspect','claim')),reason text not null,staff_operator uuid references auth.users(id) on delete set null,staff_notes text,suspension_duration_days integer,created_at timestamptz not null default now());
create index idx_community_action_report on public.community_moderation_actions(report_id);
create table public.community_moderation_sanctions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,report_id uuid references public.community_reports(id) on delete set null,kind text not null check(kind in ('suspend','ban')),expires_at timestamptz,reversed_at timestamptz,created_at timestamptz not null default now());
create index idx_community_sanction_user on public.community_moderation_sanctions(user_id);
create table public.community_moderation_appeals(id uuid primary key default gen_random_uuid(),report_id uuid not null references public.community_reports(id) on delete cascade,appellant_user_id uuid not null references auth.users(id) on delete cascade,reason text not null check(char_length(reason) between 1 and 1000),status text not null default 'pending' check(status in ('pending','approved','rejected')),reviewed_by uuid references auth.users(id) on delete set null,reviewer_notes text check(char_length(reviewer_notes)<=1000),resolved_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(report_id,appellant_user_id));
create index idx_community_appeal_user on public.community_moderation_appeals(appellant_user_id);
do $$ declare t text; begin foreach t in array array['community_moderation_staff','community_report_usage','community_report_receipts','community_moderation_actions','community_moderation_sanctions','community_moderation_appeals'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t); end loop;end $$;
revoke update,delete on public.community_moderation_actions from service_role;
revoke all on public.community_reports from anon,authenticated;
grant select(id,reporter_user_id,target_type,target_id,reason,notes,status,priority,decision,decision_reason,action_taken_at,suspension_expires_at,created_at,updated_at) on public.community_reports to authenticated;
create policy community_appeal_owner on public.community_moderation_appeals for select to authenticated using(appellant_user_id=auth.uid());
grant select(id,report_id,appellant_user_id,reason,status,resolved_at,created_at,updated_at) on public.community_moderation_appeals to authenticated;

create function public.community_staff_required() returns uuid language plpgsql security definer set search_path='' as $$ begin
 if auth.uid() is null or auth.jwt()->>'aal' is distinct from 'aal2' or not exists(select 1 from public.community_moderation_staff where user_id=auth.uid() and active) then raise exception 'community_access_denied'; end if;return auth.uid();end $$;
create function public.community_sanctioned(p_user_id uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.community_moderation_sanctions where user_id=p_user_id and reversed_at is null and (kind='ban' or expires_at>now())) $$;
create or replace function public.community_active(p_user_id uuid) returns boolean language sql volatile security definer set search_path='' as $$ select public.community_eligible(p_user_id) and not public.community_sanctioned(p_user_id) and exists(select 1 from public.community_profiles where user_id=p_user_id and status='active' and terms_version='2026-09-30' and terms_accepted_at is not null and adult_declared_at is not null) $$;
create function public.community_profile_sanction_guard() returns trigger language plpgsql security definer set search_path='' as $$ begin if new.status='active' and public.community_sanctioned(new.user_id) then raise exception 'community_unavailable';end if;return new;end $$;
create trigger community_profile_sanction_guard before insert or update on public.community_profiles for each row execute function public.community_profile_sanction_guard();
-- A removed profile becomes withdrawn, so later explicit consent can reenroll after expiry/reversal.
-- Cards and relationships are never resurrected by a staff action or appeal.
create function public.community_social_snapshot(p_type text,p_id text) returns jsonb language sql stable security definer set search_path='' as $$ select case when p_type='profile' then (select jsonb_build_object('handle',handle,'displayName',display_name,'avatarSymbol',avatar_symbol,'bio',bio) from public.community_profiles where user_id::text=p_id) when p_type='activity' then (select jsonb_build_object('category',category,'sharedDay',shared_day,'durationSeconds',duration_seconds) from public.shared_activities where id::text=p_id) end $$;
create function public.community_issue_report_receipt(p_target_type text,p_target_id text) returns table(id uuid) language plpgsql security definer set search_path='' as $$ declare subject uuid; snapshot jsonb; begin
 perform public.community_lock();
 if auth.uid() is null then raise exception 'community_access_denied';end if;
 if p_target_type='profile' then select p.user_id,jsonb_build_object('handle',p.handle,'displayName',p.display_name,'avatarSymbol',p.avatar_symbol,'bio',p.bio) into subject,snapshot from public.community_get_profile(p_target_id::uuid) p where p.user_id<>auth.uid();
 elsif p_target_type='activity' and public.community_can_view_card(p_target_id::uuid) then select user_id into subject from public.shared_activities where id=p_target_id::uuid and user_id<>auth.uid();end if;
 if subject is null then raise exception 'community_unavailable';end if;
 if p_target_type='activity' then snapshot:=public.community_social_snapshot(p_target_type,p_target_id);end if;
 return query insert into public.community_report_receipts(user_id,target_type,target_id,subject_user_id,evidence_snapshot) values(auth.uid(),p_target_type,p_target_id,subject,snapshot) returning community_report_receipts.id;
 end $$;
-- Server-created receipts retain evidence when the interaction disappears. No client insert privilege.
create function public.community_capture_interaction_receipt() returns trigger language plpgsql security definer set search_path='' as $$ declare u uuid; subject uuid; tid text; typ text; snap jsonb;begin
 if tg_table_name='community_relationships' then
 for u,subject in select old.follower_user_id,old.target_user_id union all select old.target_user_id,old.follower_user_id loop
 snap:=public.community_social_snapshot('profile',subject::text)-'bio';
 if snap is not null and exists(select 1 from auth.users where id=subject) and exists(select 1 from auth.users where id=u) and not exists(select 1 from public.account_deletion_jobs where user_id=u and status in ('in_progress','completed','failed')) then insert into public.community_report_receipts(user_id,target_type,target_id,subject_user_id,evidence_snapshot) values(u,'profile',subject::text,subject,snap);end if;end loop;
 else select user_id into subject from public.shared_activities where id=old.activity_id;
 if subject is not null and exists(select 1 from auth.users where id=subject) and exists(select 1 from auth.users where id=old.user_id) and not exists(select 1 from public.account_deletion_jobs where user_id=old.user_id and status in ('in_progress','completed','failed')) then insert into public.community_report_receipts(user_id,target_type,target_id,subject_user_id,evidence_snapshot) values(old.user_id,'activity',old.activity_id::text,subject,public.community_social_snapshot('activity',old.activity_id::text));end if;
 end if; if tg_op='UPDATE' then return new;end if;return old;end $$;
create trigger community_relationship_receipt before delete or update on public.community_relationships for each row execute function public.community_capture_interaction_receipt();
create trigger community_reaction_receipt before delete or update on public.community_reactions for each row execute function public.community_capture_interaction_receipt();
create function public.community_submit_report(p_target_type text,p_target_id text,p_reason text,p_notes text default null,p_interaction_receipt_id uuid default null) returns setof public.community_reports language plpgsql security definer set search_path='' as $$ declare r public.community_reports; receipt public.community_report_receipts; subject uuid; snapshot jsonb; n integer;begin
 perform public.community_lock();
 if auth.uid() is null then raise exception 'community_access_denied';end if;
 if p_target_type is null or p_reason is null or p_target_type not in ('profile','activity') or p_reason not in ('harassment','offensive_content','impersonation','spam','unsafe_or_sexual_content','other') or char_length(p_notes)>1000 then raise exception 'community_invalid_report';end if;
 if p_interaction_receipt_id is not null then select * into receipt from public.community_report_receipts where id=p_interaction_receipt_id and user_id=auth.uid() and target_type=p_target_type and target_id=p_target_id and expires_at>now();end if;
 if p_interaction_receipt_id is not null and receipt.id is null then raise exception 'community_unavailable';end if;
 if p_interaction_receipt_id is null then select * into receipt from public.community_report_receipts where user_id=auth.uid() and target_type=p_target_type and target_id=p_target_id and expires_at>now() order by created_at desc limit 1;end if;
 if receipt.id is null then
 if p_target_type='profile' then select p.user_id,jsonb_build_object('handle',p.handle,'displayName',p.display_name,'avatarSymbol',p.avatar_symbol,'bio',p.bio) into subject,snapshot from public.community_get_profile(p_target_id::uuid) p where p.user_id<>auth.uid();
 elsif public.community_can_view_card(p_target_id::uuid) then select user_id into subject from public.shared_activities where id=p_target_id::uuid and user_id<>auth.uid();end if;
 if subject is null then raise exception 'community_unavailable';end if;if p_target_type='activity' then snapshot:=public.community_social_snapshot(p_target_type,p_target_id);end if;
 else subject:=receipt.subject_user_id;snapshot:=receipt.evidence_snapshot;end if;
 select * into r from public.community_reports where reporter_user_id=auth.uid() and target_type=p_target_type and target_id=p_target_id and reason=p_reason and status in ('submitted','under_review') order by created_at limit 1 for update;
 if r.id is not null then update public.community_reports set notes=case when nullif(p_notes,'') is null then notes else left(concat_ws(E'\n',notes,p_notes),1000) end,updated_at=now() where id=r.id returning * into r;r.assigned_to:=null;r.staff_notes:=null;r.subject_user_id:=null;r.evidence_snapshot:='{}';return next r;return;end if;
 insert into public.community_report_usage(user_id,report_date,report_count) values(auth.uid(),(now() at time zone 'UTC')::date,1) on conflict(user_id,report_date) do update set report_count=community_report_usage.report_count+1 where community_report_usage.report_count<10 returning report_count into n;
 if n is null then raise exception 'community_rate_limited';end if;
 insert into public.community_reports(reporter_user_id,target_type,target_id,reason,notes,priority,subject_user_id,evidence_snapshot) values(auth.uid(),p_target_type,p_target_id,p_reason,p_notes,case when p_reason in ('harassment','unsafe_or_sexual_content') then 'urgent' else 'normal' end,subject,coalesce(snapshot,'{}')) returning * into r;r.subject_user_id:=null;r.evidence_snapshot:='{}';return next r;
 end $$;
-- Evidence reads are case scoped and append audit metadata, never health records.
create function public.community_audit_inspection(p_report_id uuid,p_reason text) returns void language plpgsql security definer set search_path='' as $$declare operator uuid;begin operator:=public.community_staff_required();insert into public.community_moderation_actions(report_id,target_type,target_id,action,reason,staff_operator) select id,target_type,target_id,'inspect',p_reason,operator from public.community_reports where id=p_report_id;end $$;
create function public.community_moderation_queue(p_status text default null,p_limit integer default 50,p_offset integer default 0) returns setof public.community_reports language plpgsql security definer set search_path='' as $$declare r public.community_reports;begin perform public.community_staff_required();for r in select * from public.community_reports where (p_status is null and status in ('submitted','under_review')) or (p_status is not null and status=p_status) order by (priority='urgent') desc,created_at,id limit greatest(1,least(coalesce(p_limit,50),100)) offset greatest(0,coalesce(p_offset,0)) loop perform public.community_audit_inspection(r.id,'Moderation queue inspection');return next r;end loop;end $$;
create function public.community_apply_moderation_action(p_report_id uuid,p_decision text,p_decision_reason text,p_staff_notes text default null,p_suspension_duration_days integer default null) returns setof public.community_reports language plpgsql security definer set search_path='' as $$declare operator uuid; r public.community_reports;begin
 operator:=public.community_staff_required();perform public.community_lock();select * into r from public.community_reports where id=p_report_id for update;
 if r.id is null or r.status not in ('submitted','under_review') then raise exception 'community_conflict';end if;
 if r.assigned_to is not null and r.assigned_to<>operator::text then raise exception 'community_conflict';end if;
 if operator=r.subject_user_id or operator=r.reporter_user_id then raise exception 'community_access_denied';end if;
 if p_decision is null or p_decision not in ('warn','remove','suspend','ban','dismiss') or nullif(btrim(p_decision_reason),'') is null or char_length(p_decision_reason)>500 or char_length(p_staff_notes)>1000 or (p_decision='suspend' and (p_suspension_duration_days is null or p_suspension_duration_days not in (7,14,30))) then raise exception 'community_invalid_action';end if;
 if p_decision in ('suspend','ban') then
 if r.subject_user_id is null then raise exception 'community_unavailable';end if;
 insert into public.community_moderation_sanctions(user_id,report_id,kind,expires_at) values(r.subject_user_id,r.id,p_decision,case when p_decision='suspend' then now()+p_suspension_duration_days*interval '1 day' end);
 update public.community_profiles set status='withdrawn',is_searchable=false,updated_at=now() where user_id=r.subject_user_id;
 elsif p_decision='remove' then if r.target_type='activity' then update public.shared_activities set revoked_at=now() where id::text=r.target_id;else update public.community_profiles set status='withdrawn',is_searchable=false,updated_at=now() where user_id=r.subject_user_id;end if;end if;
 insert into public.community_moderation_actions(report_id,target_type,target_id,action,reason,staff_operator,staff_notes,suspension_duration_days) values(r.id,r.target_type,r.target_id,p_decision,p_decision_reason,operator,p_staff_notes,p_suspension_duration_days);
 return query update public.community_reports set status=case when p_decision='dismiss' then 'dismissed' else 'resolved' end,decision=p_decision,decision_reason=p_decision_reason,staff_notes=p_staff_notes,assigned_to=operator::text,action_taken_at=now(),suspension_expires_at=case when p_decision='suspend' then now()+p_suspension_duration_days*interval '1 day' end,updated_at=now() where id=r.id returning *;end $$;
create function public.community_create_moderation_appeal(p_report_id uuid,p_reason text) returns setof public.community_moderation_appeals language plpgsql security definer set search_path='' as $$declare a public.community_moderation_appeals;begin perform public.community_lock();if auth.uid() is null or not exists(select 1 from public.community_reports where id=p_report_id and subject_user_id=auth.uid() and status='resolved' and decision<>'dismiss') then raise exception 'community_access_denied';end if;insert into public.community_moderation_appeals(report_id,appellant_user_id,reason) values(p_report_id,auth.uid(),p_reason) on conflict(report_id,appellant_user_id) do update set reason=community_moderation_appeals.reason returning * into a;a.reviewed_by:=null;a.reviewer_notes:=null;return next a;end $$;
create function public.community_resolve_moderation_appeal(p_appeal_id uuid,p_status text,p_reviewer_notes text default null) returns setof public.community_moderation_appeals language plpgsql security definer set search_path='' as $$declare operator uuid;a public.community_moderation_appeals;r public.community_reports;begin operator:=public.community_staff_required();perform public.community_lock();select * into a from public.community_moderation_appeals where id=p_appeal_id for update;select * into r from public.community_reports where id=a.report_id for update;
 if a.id is null or a.status<>'pending' then raise exception 'community_conflict';end if;
 if operator=a.appellant_user_id or operator::text=r.assigned_to or operator=r.reporter_user_id then raise exception 'community_access_denied';end if;
 if p_status is null or p_status not in ('approved','rejected') or char_length(p_reviewer_notes)>1000 then raise exception 'community_invalid_action';end if;
 if p_status='approved' then update public.community_moderation_sanctions set reversed_at=now() where report_id=r.id and reversed_at is null;insert into public.community_moderation_actions(report_id,target_type,target_id,action,reason,staff_operator,staff_notes) values(r.id,r.target_type,r.target_id,'reverse','Appeal approved',operator,p_reviewer_notes);end if;
 return query update public.community_moderation_appeals set status=p_status,reviewed_by=operator,reviewer_notes=p_reviewer_notes,resolved_at=now(),updated_at=now() where id=a.id returning *;end $$;
-- RPC owner output avoids internal reviewer identity/notes even on INSERT return.
create function public.community_get_appeal(p_appeal_id uuid) returns table(id uuid,report_id uuid,appellant_user_id uuid,reason text,status text,resolved_at timestamptz,created_at timestamptz,updated_at timestamptz) language plpgsql volatile security definer set search_path='' as $$declare staff boolean;case_id uuid;begin
 select exists(select 1 from public.community_moderation_staff where user_id=auth.uid() and active) and auth.jwt()->>'aal'='aal2' into staff;
 if coalesce(staff,false) then select a.report_id into case_id from public.community_moderation_appeals a where a.id=p_appeal_id;if case_id is not null then perform public.community_audit_inspection(case_id,'Appeal evidence inspection');end if;end if;
 return query select a.id,a.report_id,a.appellant_user_id,a.reason,a.status,a.resolved_at,a.created_at,a.updated_at from public.community_moderation_appeals a where a.id=p_appeal_id and (a.appellant_user_id=auth.uid() or coalesce(staff,false));end $$;
create function public.community_report_receipts_for_caller() returns table(id uuid,target_type text,target_id text,expires_at timestamptz) language sql stable security definer set search_path='' as $$ select id,target_type,target_id,expires_at from public.community_report_receipts where user_id=auth.uid() and expires_at>now() order by created_at desc limit 100 $$;
create function public.community_moderation_notices() returns setof public.community_reports language plpgsql stable security definer set search_path='' as $$declare r public.community_reports;begin for r in select * from public.community_reports where subject_user_id=auth.uid() and status='resolved' order by action_taken_at desc limit 100 loop r.reporter_user_id:=auth.uid();r.notes:=null;r.decision_reason:=null;r.staff_notes:=null;r.assigned_to:=null;r.subject_user_id:=null;r.evidence_snapshot:='{}';return next r;end loop;end $$;
create function public.community_get_report(p_report_id uuid) returns setof public.community_reports language plpgsql volatile security definer set search_path='' as $$declare r public.community_reports;staff boolean;begin
 if auth.uid() is null then raise exception 'community_access_denied';end if;
 select exists(select 1 from public.community_moderation_staff where user_id=auth.uid() and active) and auth.jwt()->>'aal'='aal2' into staff;
 select * into r from public.community_reports where id=p_report_id and (staff or reporter_user_id=auth.uid());
 if r.id is null then return;end if;
 if coalesce(staff,false) then perform public.community_audit_inspection(r.id,'Case evidence inspection');end if;
 if not coalesce(staff,false) then r.staff_notes:=null;r.assigned_to:=null;r.subject_user_id:=null;r.evidence_snapshot:='{}';end if;return next r;end $$;
create function public.community_text_safe(p_text text) returns boolean language sql immutable set search_path='' as $$ select p_text is null or normalize(p_text,NFKC) !~* '\m(kill[[:space:]]+yourself|kys|die[[:space:]]+in[[:space:]]+a[[:space:]]+fire|hate[[:space:]]+speech|pro-?ana|thinspo|bonespo|fat[[:space:]]*pig|anorexia[[:space:]]*tips|starvation[[:space:]]*challenge|dry[[:space:]]*fast(ing)?|dnp[[:space:]]*(cycle|burn)|no[[:space:]]*water|anabolic[[:space:]]*steroids?[[:space:]]*source|buy[[:space:]]*followers|free[[:space:]]*crypto|telegram[[:space:]]*@|whatsapp[[:space:]]*|invest[[:space:]]*guaranteed[[:space:]]*return|cashapp[[:space:]]*flip|mizyun[[:space:]]*(support|admin|staff|official)|official[[:space:]]*mizyun|csam|csae|child[[:space:]]*porn|pedophil|underage[[:space:]]*nude)\M' $$;
create function public.community_profile_content_guard() returns trigger language plpgsql security definer set search_path='' as $$begin if not public.community_text_safe(replace(new.handle,'_',' ')) or not public.community_text_safe(new.display_name) or not public.community_text_safe(new.bio) then raise exception 'community_invalid_profile';end if;return new;end $$;
create trigger community_profile_content_guard before insert or update of handle,display_name,bio on public.community_profiles for each row execute function public.community_profile_content_guard();
-- Invitation bearers expose only the minimal displayed identity; retain exactly that
-- projection as caller-owned evidence, even when the inviter disabled discovery.
create or replace function public.community_resolve_invitation(p_token text) returns table(invitation jsonb, inviter jsonb)
language plpgsql volatile security definer set search_path = '' as $$
declare i public.community_invitations; p public.community_profiles;
begin
 perform public.community_lock();
 perform public.community_discovery_attempt();
 select * into i from public.community_invitations where token = p_token and revoked_at is null and expires_at > now();
 if i.id is null or not public.community_active(i.inviter_user_id) or public.community_blocked_between(auth.uid(),i.inviter_user_id) then return; end if;
 select * into p from public.community_profiles where user_id = i.inviter_user_id;
 if p.generation <> i.enrollment_generation then return; end if;
 if p.user_id<>auth.uid() then
 insert into public.community_report_receipts(user_id,target_type,target_id,subject_user_id,evidence_snapshot)
 values(auth.uid(),'profile',p.user_id::text,p.user_id,jsonb_build_object('handle',p.handle,'displayName',p.display_name,'avatarSymbol',p.avatar_symbol,'bio',null));
 end if;
 return query select jsonb_build_object('id',i.id,'token',i.token,'inviter_user_id',i.inviter_user_id,
 'expires_at',i.expires_at,'revoked_at',i.revoked_at,'created_at',i.created_at), jsonb_build_object('user_id',p.user_id,'handle',p.handle,'display_name',p.display_name,
 'avatar_symbol',p.avatar_symbol,'bio',null,'is_searchable',p.is_searchable,'status','active','generation',1,'created_at',p.created_at,'updated_at',p.updated_at);
end $$;
create function public.community_has_recent_interaction(p_caller uuid,p_target_id text,p_target_type text default 'profile',p_window_days integer default 30) returns table(result boolean) language plpgsql stable security definer set search_path='' as $$begin if auth.uid() is null or p_caller is distinct from auth.uid() then raise exception 'community_access_denied';end if;return query select exists(select 1 from public.community_report_receipts where user_id=auth.uid() and target_type=p_target_type and target_id=p_target_id and expires_at>now() and created_at>now()-greatest(1,least(coalesce(p_window_days,30),30))*interval '1 day');end $$;
create function public.community_claim_report(p_report_id uuid) returns setof public.community_reports language plpgsql security definer set search_path='' as $$declare operator uuid;r public.community_reports;begin operator:=public.community_staff_required();perform public.community_lock();select * into r from public.community_reports where id=p_report_id for update;if r.id is null or r.status not in ('submitted','under_review') or (r.assigned_to is not null and r.assigned_to<>operator::text) then raise exception 'community_conflict';end if;if operator=r.subject_user_id or operator=r.reporter_user_id then raise exception 'community_access_denied';end if;insert into public.community_moderation_actions(report_id,target_type,target_id,action,reason,staff_operator) values(r.id,r.target_type,r.target_id,'claim','Case assigned to named operator',operator);return query update public.community_reports set assigned_to=operator::text,status='under_review',updated_at=now() where id=p_report_id returning *;end $$;
create function public.community_moderation_appeals_queue(p_limit integer default 50,p_offset integer default 0) returns setof public.community_moderation_appeals language plpgsql volatile security definer set search_path='' as $$declare a public.community_moderation_appeals;begin perform public.community_staff_required();for a in select * from public.community_moderation_appeals where status='pending' order by created_at,id limit greatest(1,least(coalesce(p_limit,50),100)) offset greatest(0,coalesce(p_offset,0)) loop perform public.community_audit_inspection(a.report_id,'Appeal queue inspection');return next a;end loop;end $$;
do $$declare r record;begin for r in select p.oid::regprocedure as signature,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('community_staff_required','community_sanctioned','community_profile_sanction_guard','community_social_snapshot','community_issue_report_receipt','community_capture_interaction_receipt','community_submit_report','community_moderation_queue','community_apply_moderation_action','community_create_moderation_appeal','community_resolve_moderation_appeal','community_get_appeal','community_report_receipts_for_caller','community_moderation_notices','community_get_report','community_text_safe','community_profile_content_guard','community_has_recent_interaction','community_claim_report','community_moderation_appeals_queue','community_audit_inspection') loop execute format('revoke all on function %s from public,anon,authenticated,service_role',r.signature);if r.proname in ('community_issue_report_receipt','community_submit_report','community_moderation_queue','community_apply_moderation_action','community_create_moderation_appeal','community_resolve_moderation_appeal','community_get_appeal','community_report_receipts_for_caller','community_moderation_notices','community_get_report','community_has_recent_interaction','community_claim_report','community_moderation_appeals_queue') then execute format('grant execute on function %s to authenticated',r.signature);end if;end loop;end $$;
commit;
